"use client";

/**
 * Form Preview
 *
 * An interactive simulation of the form: real enabled inputs, conditional
 * logic evaluated live against what you type (the same evaluator the
 * runtime uses), the form's actual settings (button text, confirmation
 * behavior), and a device-width toggle. It is honest about what it is —
 * a faithful simulation inside the admin, not the published form; nothing
 * here submits anywhere.
 *
 * @module admin/components/builder/FormPreview
 */

import {
  Badge,
  Button,
  Checkbox,
  Input,
  Card,
  Label,
  RadioGroup,
  RadioGroupItem,
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
  Tabs,
  TabsList,
  TabsTrigger,
  Textarea,
} from "@nextlyhq/ui";
import { Eye, Monitor, Paperclip, RotateCcw, Smartphone } from "lucide-react";
import { type JSX, useMemo, useState } from "react";

import type { AnyFormField, CustomFormField, FormField } from "../../../types";
import { isKnownFormField } from "../../../types";
import { evaluateConditions } from "../../../utils/evaluate-conditions";
import { useFormBuilder } from "../../context/FormBuilderContext";

import { hasStoredRedirectPage } from "./FormSettingsTab";

// ---------------------------------------------------------------------------
// Field rendering
// ---------------------------------------------------------------------------

function PreviewFieldInput({
  field,
  value,
  onChange,
}: {
  field: FormField;
  value: unknown;
  onChange: (value: unknown) => void;
}) {
  const id = `preview-${field.name}`;
  switch (field.type) {
    case "textarea":
      return (
        <Textarea
          id={id}
          value={typeof value === "string" ? value : ""}
          onChange={e => onChange(e.target.value)}
          rows={"rows" in field ? (field.rows ?? 4) : 4}
          placeholder={field.placeholder}
        />
      );
    case "checkbox":
      // A real checkbox, not a toggle switch — the preview should look like
      // what a frontend form renders for this type.
      return (
        <Checkbox
          id={id}
          checked={Boolean(value)}
          onCheckedChange={checked => onChange(checked === true)}
        />
      );
    case "select": {
      const options = "options" in field ? (field.options ?? []) : [];
      return (
        <Select
          value={typeof value === "string" ? value : ""}
          onValueChange={onChange}
        >
          <SelectTrigger
            id={id}
            className="w-full bg-transparent border-input dark:bg-muted/50"
          >
            <SelectValue placeholder={field.placeholder ?? "Select…"} />
          </SelectTrigger>
          <SelectContent>
            {options.map(option => (
              <SelectItem key={option.value} value={option.value}>
                {option.label}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      );
    }
    case "radio": {
      const options = "options" in field ? (field.options ?? []) : [];
      return (
        <RadioGroup
          value={typeof value === "string" ? value : ""}
          onValueChange={onChange}
          className="flex flex-col gap-2"
        >
          {options.map(option => (
            <div key={option.value} className="flex items-center gap-2">
              <RadioGroupItem
                value={option.value}
                id={`${id}-${option.value}`}
              />
              <Label htmlFor={`${id}-${option.value}`} className="font-normal">
                {option.label}
              </Label>
            </div>
          ))}
        </RadioGroup>
      );
    }
    case "number":
      return (
        <Input
          id={id}
          type="number"
          value={
            typeof value === "number" || typeof value === "string"
              ? String(value)
              : ""
          }
          onChange={e =>
            onChange(e.target.value === "" ? "" : Number(e.target.value))
          }
          placeholder={field.placeholder}
        />
      );
    case "date":
    case "time":
      return (
        <Input
          id={id}
          type={field.type}
          value={typeof value === "string" ? value : ""}
          onChange={e => onChange(e.target.value)}
        />
      );
    case "file":
      // Nothing uploads from a preview; the affordance is shown, disabled.
      return (
        <div className="flex items-center gap-2 border border-dashed border-border bg-muted/40 px-3 py-2 text-sm text-muted-foreground">
          <Paperclip className="h-4 w-4" aria-hidden="true" />
          File upload (disabled in preview)
        </div>
      );
    default:
      return (
        <Input
          id={id}
          type={
            field.type === "email"
              ? "email"
              : field.type === "url"
                ? "url"
                : field.type === "phone"
                  ? "tel"
                  : "text"
          }
          value={typeof value === "string" ? value : ""}
          onChange={e => onChange(e.target.value)}
          placeholder={field.placeholder}
        />
      );
  }
}

/**
 * Preview for a plugin-contributed field. The plugin owns the real input, which
 * renders from its own component in the live form; the builder preview shows a
 * labeled placeholder so the field's presence and order stay visible.
 */
function PluginFieldPreview({ field }: { field: CustomFormField }) {
  return (
    <div className="space-y-1.5">
      <Label htmlFor={`preview-${field.name}`}>
        {field.label || field.name}
        {field.required && <span className="ml-1 text-destructive">*</span>}
      </Label>
      <div className="flex items-center gap-2 border border-dashed border-border bg-muted/40 px-3 py-2 text-sm text-muted-foreground">
        Custom field ({field.type}) — renders from its plugin component in the
        live form.
      </div>
      {field.helpText && (
        <p className="text-xs text-muted-foreground">{field.helpText}</p>
      )}
    </div>
  );
}

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export interface FormPreviewProps {
  /** Array of form fields to preview (built-in or plugin-contributed). */
  fields: AnyFormField[];
  /** Form metadata */
  formData?: {
    name?: string;
    slug?: string;
    description?: string;
  };
}

/**
 * What the visitor is told after a successful submission.
 *
 * Its own component because the fall-through belongs to the MESSAGE branch: a
 * confirmation this does not name is previewed as a thank-you note, which is
 * how the page redirect came to be previewed as something it is not. Each
 * confirmation that is not a message has to be named here.
 */
function Confirmation({
  settings,
}: {
  settings: {
    confirmationType?: string;
    redirectUrl?: string;
    successMessage?: string;
    redirectPage?: unknown;
  };
}) {
  const panel = "border border-border bg-muted/40 p-4 text-sm text-foreground";

  if (settings.confirmationType === "redirect") {
    return (
      <p className={panel}>
        The visitor would now be redirected to{" "}
        <span className="font-mono">
          {settings.redirectUrl || "(no redirect URL set)"}
        </span>
        .
      </p>
    );
  }

  if (settings.confirmationType === "relationship") {
    // Whether a page is actually named, not merely that this confirmation is
    // chosen. Claiming a redirect with no page saved describes something that
    // cannot happen: the save is refused, and a form that reached this state
    // another way resolves to no redirect at all.
    const named = hasStoredRedirectPage(settings);
    return (
      <p className={panel}>
        {named
          ? "The visitor would now be redirected to the linked page. Its URL is built when the form is submitted, from the pattern the site configured for that collection."
          : "No page is selected yet, so this form has no destination. Choose one under Settings, or pick a different confirmation."}
      </p>
    );
  }

  return (
    <p className={panel}>
      {settings.successMessage || "Thank you for your submission!"}
    </p>
  );
}

export function FormPreview({
  fields,
  formData,
}: FormPreviewProps): JSX.Element {
  const { settings } = useFormBuilder();
  const [values, setValues] = useState<Record<string, unknown>>({});
  const [device, setDevice] = useState<"desktop" | "mobile">("desktop");
  const [confirmed, setConfirmed] = useState(false);
  const [missingRequired, setMissingRequired] = useState<Set<string>>(
    new Set()
  );

  // Conditional logic runs against the live values with the SAME evaluator
  // the runtime uses — typing into the preview shows/hides fields for real.
  // Visibility is computed in field order against the values of fields that
  // are themselves visible: a hidden field's leftover value must not keep
  // satisfying a downstream condition (chained show/hide would misbehave).
  const visibleFields = useMemo(() => {
    const effectiveValues: Record<string, unknown> = {};
    const visible: AnyFormField[] = [];
    for (const field of fields) {
      if (field.type === "hidden") continue;
      const isVisible =
        !field.conditionalLogic?.enabled ||
        evaluateConditions(field.conditionalLogic, effectiveValues);
      if (isVisible) {
        visible.push(field);
        if (field.name in values) {
          effectiveValues[field.name] = values[field.name];
        }
      }
    }
    return visible;
  }, [fields, values]);

  const hiddenCount = fields.filter(field => field.type === "hidden").length;

  const reset = () => {
    setValues({});
    setConfirmed(false);
    setMissingRequired(new Set());
  };

  // The real form would refuse an empty required field, so the simulation
  // does too — an admin previewing required fields sees the requirement.
  const simulateSubmit = () => {
    const missing = new Set(
      visibleFields
        .filter(field => {
          // A plugin field renders a non-interactive placeholder in the preview
          // (its real input lives in the plugin's component in the live form),
          // so it can never be filled here — excluded like `file`, otherwise the
          // simulated submit would block forever with no way to satisfy it.
          if (!field.required || field.type === "file") return false;
          if (!isKnownFormField(field)) return false;
          const value = values[field.name];
          return value === undefined || value === "" || value === false;
        })
        .map(field => field.name)
    );
    setMissingRequired(missing);
    if (missing.size === 0) setConfirmed(true);
  };

  return (
    // One surface for the whole tab. The chrome and the stage are the same
    // panel seen twice, and leaving the chrome unbacked put it on the page's
    // grey while the stage below it had a frame — reading as a control strip
    // that had lost its box.
    <Card className="overflow-hidden p-0">
      {/* Preview chrome: honest framing + device toggle + reset */}
      <div className="flex flex-col gap-3 border-b border-border px-6 py-4 sm:flex-row sm:items-center sm:justify-between">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Eye className="h-4 w-4" aria-hidden="true" />
          Preview — a simulation of this form. Nothing here submits anywhere.
        </div>
        {/* Wraps rather than holding one row. The card around this clips, and
            at a ~360px panel the inset leaves less width than the device
            toggle and Reset need side by side — so an unwrapped row loses its
            right edge instead of overflowing visibly. */}
        <div className="flex flex-wrap items-center justify-end gap-2">
          <Tabs
            value={device}
            onValueChange={value => setDevice(value as "desktop" | "mobile")}
          >
            {/* No corner override: the primitive already guarantees square,
                and a call site restating it is how the guarantee gets forked. */}
            <TabsList>
              <TabsTrigger value="desktop" className="gap-1.5">
                <Monitor className="h-3.5 w-3.5" aria-hidden="true" />
                Desktop
              </TabsTrigger>
              <TabsTrigger value="mobile" className="gap-1.5">
                <Smartphone className="h-3.5 w-3.5" aria-hidden="true" />
                Mobile
              </TabsTrigger>
            </TabsList>
          </Tabs>
          <Button type="button" variant="outline" size="sm" onClick={reset}>
            <RotateCcw className="h-3.5 w-3.5" aria-hidden="true" />
            Reset
          </Button>
        </div>
      </div>

      {/* The simulated form, on a tinted stage so the sheet inside reads as a
          page rather than as more of this panel. The stage draws no border of
          its own — the card around it already does. */}
      <div className="flex justify-center bg-muted/30 p-6">
        <div
          className={`w-full space-y-5 border border-border bg-background p-6 ${
            device === "mobile" ? "max-w-95" : "max-w-2xl"
          }`}
        >
          <div>
            <h3 className="text-lg font-semibold text-foreground">
              {formData?.name || "Untitled form"}
            </h3>
            {formData?.description && (
              <p className="mt-1 text-sm text-muted-foreground">
                {formData.description}
              </p>
            )}
          </div>

          {confirmed ? (
            <div className="space-y-4">
              <Confirmation settings={settings} />
              <Button type="button" variant="outline" onClick={reset}>
                Fill again
              </Button>
            </div>
          ) : (
            <>
              {visibleFields.length === 0 && (
                <p className="text-sm text-muted-foreground">
                  No visible fields — add fields in the Builder tab.
                </p>
              )}
              {visibleFields.map(field =>
                !isKnownFormField(field) ? (
                  <PluginFieldPreview key={field.name} field={field} />
                ) : (
                  <div key={field.name} className="space-y-1.5">
                    {field.type !== "checkbox" && (
                      <Label htmlFor={`preview-${field.name}`}>
                        {field.label || field.name}
                        {field.required && (
                          <span className="ml-1 text-destructive">*</span>
                        )}
                      </Label>
                    )}
                    {field.type === "checkbox" ? (
                      <div className="flex items-center gap-2">
                        <PreviewFieldInput
                          field={field}
                          value={values[field.name]}
                          onChange={value =>
                            setValues(prev => ({
                              ...prev,
                              [field.name]: value,
                            }))
                          }
                        />
                        <Label htmlFor={`preview-${field.name}`}>
                          {field.label || field.name}
                          {field.required && (
                            <span className="ml-1 text-destructive">*</span>
                          )}
                        </Label>
                      </div>
                    ) : (
                      <PreviewFieldInput
                        field={field}
                        value={values[field.name]}
                        onChange={value =>
                          setValues(prev => ({ ...prev, [field.name]: value }))
                        }
                      />
                    )}
                    {field.helpText && (
                      <p className="text-xs text-muted-foreground">
                        {field.helpText}
                      </p>
                    )}
                    {missingRequired.has(field.name) && (
                      <p className="text-xs text-destructive">
                        This field is required.
                      </p>
                    )}
                  </div>
                )
              )}

              <Button
                type="button"
                onClick={simulateSubmit}
                disabled={visibleFields.length === 0}
              >
                {settings.submitButtonText || "Submit"}
              </Button>
            </>
          )}

          {hiddenCount > 0 && !confirmed && (
            <p className="text-xs text-muted-foreground">
              <Badge
                variant="outline"
                className="mr-1.5 rounded-none border-border px-1 py-0 text-[10px]"
              >
                {hiddenCount}
              </Badge>
              hidden {hiddenCount === 1 ? "field" : "fields"} will be submitted
              invisibly.
            </p>
          )}
        </div>
      </div>
    </Card>
  );
}

export default FormPreview;
